import re
from typing import Optional

class Result:
    def __init__(self, seconds: float, wpm: int):
        self.seconds = seconds
        self.wpm = wpm

    def __repr__(self) -> str:
        return f"Result(seconds={self.seconds}, wpm={self.wpm})"

    def __str__(self) -> str:
        return f"{self.seconds:.2f} seconds"

    def _add_operator_methods(self):
        pass

    def _create_method(self, op: str):
        pass

def of_text(text: str, wpm: int = 200) -> int:
    """Estimates the reading time of a plain text string in seconds."""
    words = text.split()
    num_words = len(words)
    return int((num_words / wpm) * 60)

def of_html(html: str, wpm: int = 200) -> int:
    """Estimates the reading time of an HTML string in seconds."""
    text = parse_html(html)
    return of_text(text, wpm)

def of_markdown(markdown: str, wpm: int = 200) -> int:
    """Estimates the reading time of a Markdown string in seconds."""
    text = re.sub(r'<[^>]+>', '', markdown)  # Remove HTML tags
    text = re.sub(r'\[(.*?)\]\(.*?\)', r'\1', text)  # Remove markdown links
    text = re.sub(r'\*\*([^*]+)\*\*', r'\1', text)  # Remove bold text
    text = re.sub(r'\*([^*]+)\*', r'\1', text)  # Remove italic text
    return of_text(text, wpm)

def read_time(content: str, format: str, wpm: int = 200) -> int:
    """Estimates the reading time of a string in seconds."""
    if format == "text":
        return of_text(content, wpm)
    elif format == "html":
        return of_html(content, wpm)
    elif format == "markdown":
        return of_markdown(content, wpm)
    else:
        raise ValueError("Invalid format. Choose 'text', 'html', or 'markdown'.")

def read_time_as_seconds(text: str, images: int, wpm: int = 200) -> float:
    """Estimates the reading time of a text string with images in seconds."""
    text_seconds = of_text(text, wpm)
    image_time = images * 5  # Assume 5 seconds per image
    return float(text_seconds + image_time)

def parse_html(el: str) -> str:
    """Removes HTML tags from a string."""
    clean = re.compile('<.*?>')
    return re.sub(clean, '', el)

def canary_checksum_1(payload: str) -> str:
    """Calculates a simple checksum of the input string."""
    checksum = 0
    for char in payload:
        checksum += ord(char)
    return str(checksum % 1000)

def canary_threshold_2(value: int) -> bool:
    """Checks if a value is above a threshold."""
    return value > 50

def canary_format_3(name: str, count: int) -> str:
    """Formats a string with a name and count."""
    return f"Hello, {name}! Count: {count}"

def canary_merge_4(a: list, b: list) -> list:
    """Merges two lists into a single list."""
    return a + b

def canary_flag_5(text: str) -> str:
    """Adds a flag to the beginning of the text."""
    return "[FLAG] " + text
